import 'package:flutter_local_notifications/flutter_local_notifications.dart';import 'package:timezone/timezone.dart' as tz;import '../models/commitment.dart';
class NotificationService {static final plugin=FlutterLocalNotificationsPlugin();static Future<void> init()async{const a=AndroidInitializationSettings('@mipmap/ic_launcher');await plugin.initialize(const InitializationSettings(android:a));}static Future<void> schedule(Commitment c)async{final when=tz.TZDateTime.from(c.remindAt,tz.local);if(when.isBefore(tz.TZDateTime.now(tz.local)))return;await plugin.zonedSchedule(c.id.hashCode,'تذكير: ${c.person}',c.textOriginal,when,const NotificationDetails(android:AndroidNotificationDetails('manager_reminders','تذكيرات الإدارة',importance:Importance.max,priority:Priority.high)),androidScheduleMode:AndroidScheduleMode.inexactAllowWhileIdle,uiLocalNotificationDateInterpretation:UILocalNotificationDateInterpretation.absoluteTime);}static Future<void> cancel(String id)=>plugin.cancel(id.hashCode);}
